/** Virtual gamepad overlay for mobile/touch input (Tier 2c).
 *
 * Renders a translucent D-pad + ABXY + program-row buttons in HTML/CSS that
 * map to GameActions. Touch events → action dispatch via callback.
 *
 * Auto-shows on devices with `pointer: coarse` (touch); auto-hides on
 * devices with `pointer: fine` (mouse/trackpad).
 *
 * Responsive layout:
 * - Portrait: D-pad bottom-left, AB buttons bottom-right, program row above
 * - Landscape: D-pad left-center, AB buttons right-center, program row bottom
 *
 * The program row is rendered via `updateProgramRow(rows)` which main.ts
 * calls on every state change during combat. Outside combat the row is hidden.
 */

import type { GameAction } from "../core/types";
import {
  affordanceAriaLabel,
  touchAffordanceLines,
  type ProgramAffordance,
} from "../core/combat/program_affordance";

/** Minimum touch-target edge in CSS px (Apple HIG 44pt, WCAG 2.5.5).
 *
 * Buttons are sized in vw/vh so they scale on wide screens; this floor only
 * takes effect on narrow viewports where the vw size would fall below it.
 */
export const MIN_TOUCH_TARGET_PX = 44;

interface ButtonConfig {
  readonly label: string;
  readonly left: string;
  readonly top: string;
  readonly size: string;
  readonly fontSize: string;
  readonly action: GameAction;
}

interface LayoutConfig {
  readonly dpadCenterX: number;
  readonly dpadCenterY: number;
  readonly dpadButtonSize: number;
  readonly dpadOffset: number;
  readonly btnCenterX: number;
  readonly btnCenterY: number;
}

const LAYOUTS: Record<string, LayoutConfig> = {
  portrait: {
    dpadCenterX: 18,
    dpadCenterY: 75,
    dpadButtonSize: 14,
    dpadOffset: 7,
    btnCenterX: 82,
    btnCenterY: 75,
  },
  landscape: {
    dpadCenterX: 12,
    dpadCenterY: 50,
    dpadButtonSize: 12,
    dpadOffset: 6,
    btnCenterX: 88,
    btnCenterY: 50,
  },
};

function getLayoutConfig(): LayoutConfig {
  if (typeof window === "undefined") return LAYOUTS.landscape;
  const isPortrait = window.matchMedia("(orientation: portrait)").matches;
  return isPortrait ? LAYOUTS.portrait : LAYOUTS.landscape;
}

function buildDpadButtons(config: LayoutConfig): ReadonlyArray<ButtonConfig> {
  const { dpadCenterX, dpadCenterY, dpadButtonSize, dpadOffset } = config;
  return [
    {
      label: "↑",
      left: `${dpadCenterX - dpadButtonSize / 2}vw`,
      top: `${dpadCenterY - dpadButtonSize / 2 - dpadOffset}vh`,
      size: `${dpadButtonSize}vw`,
      fontSize: `${Math.round(dpadButtonSize * 0.5)}vw`,
      action: { type: "move_north" as const },
    },
    {
      label: "↓",
      left: `${dpadCenterX - dpadButtonSize / 2}vw`,
      top: `${dpadCenterY - dpadButtonSize / 2 + dpadOffset}vh`,
      size: `${dpadButtonSize}vw`,
      fontSize: `${Math.round(dpadButtonSize * 0.5)}vw`,
      action: { type: "move_south" as const },
    },
    {
      label: "←",
      left: `${dpadCenterX - dpadButtonSize / 2 - dpadOffset}vw`,
      top: `${dpadCenterY - dpadButtonSize / 2}vh`,
      size: `${dpadButtonSize}vw`,
      fontSize: `${Math.round(dpadButtonSize * 0.5)}vw`,
      action: { type: "move_west" as const },
    },
    {
      label: "→",
      left: `${dpadCenterX - dpadButtonSize / 2 + dpadOffset}vw`,
      top: `${dpadCenterY - dpadButtonSize / 2}vh`,
      size: `${dpadButtonSize}vw`,
      fontSize: `${Math.round(dpadButtonSize * 0.5)}vw`,
      action: { type: "move_east" as const },
    },
  ];
}

function buildActionButtons(config: LayoutConfig): ReadonlyArray<ButtonConfig> {
  const { btnCenterX, btnCenterY } = config;
  return [
    {
      label: "A",
      left: `${btnCenterX - 7}vw`,
      top: `${btnCenterY - 7}vh`,
      size: "14vw",
      fontSize: "7vw",
      action: { type: "confirm" as const },
    },
    {
      label: "B",
      left: `${btnCenterX - 24}vw`,
      top: `${btnCenterY - 5}vh`,
      size: "12vw",
      fontSize: "6vw",
      action: { type: "jack_out" as const },
    },
  ];
}

/** Inject CSS + DOM elements for the on-screen gamepad. */
export function mountVirtualGamepad(
  handler: (action: GameAction) => void,
): () => void {
  if (typeof document === "undefined") {
    return () => {};
  }
  const root = ensureOverlayRoot();
  renderOverlay(root, handler);
  return () => {
    root.innerHTML = "";
  };
}

/** Minimum interval between two accepted program-button presses (ms).
 *
 * P12 — the previous 250ms window dropped taps during deliberate rapid
 * play. 120ms still rejects the synthetic `pointerdown` → `click` duplicate
 * while letting a fast player register consecutive presses.
 */
export const PROGRAM_PRESS_DEBOUNCE_MS = 120;

/** Update the program row (only visible during combat).
 *
 * ADR-0251: `rows` are the same affordance rows the canvas hand draws
 * (`programAffordances`), so each button states the same facts as its canvas
 * row — slot number, name, COST, COST after (or BLOCKED), target — visibly
 * and in its `aria-label`. The buttons sit in a horizontal row at the
 * bottom-center of the viewport, over the canvas hand band, which the canvas
 * leaves empty while the overlay is mounted (`handOnOverlay`).
 *
 * `onProgramPress` receives the 1-based hand index of the pressed button. When
 * it is omitted the press falls back to the `window.wetrun` global — the direct
 * callback is preferred because the global is only assigned after boot, so a
 * tap landing in that window would otherwise be silently dropped.
 */
export function updateProgramRow(
  rows: ReadonlyArray<ProgramAffordance>,
  onProgramPress?: (handIndex: number) => void,
): void {
  const row = document.getElementById("wetrun-program-row");
  if (!row) return;
  if (rows.length === 0) {
    row.innerHTML = "";
    return;
  }
  const programMinSize =
    `min-height:max(${MIN_TOUCH_TARGET_PX}px, 6vh);` +
    `min-width:max(${MIN_TOUCH_TARGET_PX}px, 8vw)`;
  const buttons = rows.map((a) => {
    const lines = touchAffordanceLines(a)
      .map((line) => `<span>${escapeHtml(line)}</span>`)
      .join("");
    const blocked = a.blocked ? ' data-blocked="true"' : "";
    return `<button data-hand-index="${a.slot}"${blocked} aria-label="${escapeHtml(affordanceAriaLabel(a))}" style="${programMinSize};">${lines}</button>`;
  });
  row.innerHTML = `
    <style>
      #wetrun-program-row {
        position: fixed; left: 50%; transform: translateX(-50%);
        bottom: 2vh;
        display: flex; gap: 1vw;
        pointer-events: none;
        font-family: monospace;
        z-index: 6;
      }
      #wetrun-program-row button {
        pointer-events: auto;
        background: #000; border: 2px solid #00ff41;
        color: #00ff41; font-weight: bold; font-family: monospace;
        border-radius: 8px;
        touch-action: none; user-select: none;
        ${programMinSize};
        padding: 1vh 0.8vw; font-size: 3vw; line-height: 1.15;
        display: flex; flex-direction: column; align-items: center;
        justify-content: center; white-space: pre;
      }
      #wetrun-program-row button[data-blocked="true"] {
        border-color: #909090; color: #909090;
      }
      #wetrun-program-row button:active { background: rgba(0, 255, 65, 0.4); }
      #wetrun-program-row button:focus-visible {
        outline: 2px solid #ffa500; outline-offset: 2px;
      }
    </style>
    ${buttons.join("")}
  `;
  row.querySelectorAll("button").forEach((btn) => {
    const idx = Number((btn as HTMLElement).dataset.handIndex);
    if (Number.isFinite(idx) && idx > 0) {
      let lastFire = 0;
      btn.addEventListener("pointerdown", (e) => {
        e.preventDefault();
        const now = Date.now();
        if (now - lastFire < PROGRAM_PRESS_DEBOUNCE_MS) return;
        lastFire = now;
        if (onProgramPress) {
          onProgramPress(idx);
          return;
        }
        const w = window as unknown as {
          wetrun?: { handleProgramButton(handIndex: number): void };
        };
        w.wetrun?.handleProgramButton(idx);
      });
    }
  });
}

function ensureOverlayRoot(): HTMLElement {
  let root = document.getElementById("wetrun-gamepad-root");
  if (!root) {
    root = document.createElement("div");
    root.id = "wetrun-gamepad-root";
    root.setAttribute("aria-label", "Virtual gamepad");
    document.body.appendChild(root);
    const row = document.createElement("div");
    row.id = "wetrun-program-row";
    document.body.appendChild(row);
  }
  return root;
}

function renderOverlay(
  root: HTMLElement,
  handler: (action: GameAction) => void,
): void {
  const config = getLayoutConfig();
  const dpadButtons = buildDpadButtons(config);
  const actionButtons = buildActionButtons(config);

  root.innerHTML = `
    <style>
      #wetrun-gamepad-root {
        position: fixed; inset: 0;
        font-family: monospace;
        z-index: 5;
        pointer-events: auto;
      }
      #wetrun-gamepad-root button {
        position: absolute; pointer-events: auto;
        background: rgba(0, 0, 0, 0.55); border: 2px solid #00ff41;
        color: #00ff41; font-weight: bold;
        padding: 0; margin: 0; line-height: 1;
        border-radius: 8px;
        touch-action: manipulation; user-select: none;
        display: flex; align-items: center; justify-content: center;
      }
      #wetrun-gamepad-root button:active { background: rgba(0, 255, 65, 0.4); }
    </style>
  `;
  for (const btn of dpadButtons) {
    appendButton(root, btn, handler);
  }
  for (const btn of actionButtons) {
    appendButton(root, btn, handler);
  }
}

function appendButton(
  parent: HTMLElement,
  cfg: ButtonConfig,
  handler: (action: GameAction) => void,
): void {
  const btn = document.createElement("button");
  btn.textContent = cfg.label;
  btn.style.left = cfg.left;
  btn.style.top = cfg.top;
  btn.style.width = cfg.size;
  btn.style.height = cfg.size;
  btn.style.minWidth = `${MIN_TOUCH_TARGET_PX}px`;
  btn.style.minHeight = `${MIN_TOUCH_TARGET_PX}px`;
  btn.style.fontSize = cfg.fontSize;
  // Single dispatch path: registering pointerdown + touchstart + mousedown + click
  // together fires the action 2-3x per tap (touchstart → synthetic mousedown → click).
  // Use Pointer Events where available; otherwise touch/mouse with a short debounce
  // so synthetic duplicates are ignored.
  let lastFire = 0;
  const dispatch = (e: Event): void => {
    e.preventDefault();
    const now = Date.now();
    if (now - lastFire < 250) return;
    lastFire = now;
    handler(cfg.action);
  };
  if (typeof window !== "undefined" && "PointerEvent" in window) {
    btn.addEventListener("pointerdown", dispatch);
  } else {
    btn.addEventListener("touchstart", dispatch, { passive: false });
    btn.addEventListener("mousedown", dispatch);
  }
  parent.appendChild(btn);
}

/** Returns true when the device has touch capability.
 * Checks multiple signals: pointer: coarse, any-pointer: coarse, touchstart support,
 * or maxTouchPoints > 0. E-ink devices with stylus may report pointer: fine but
 * still support touch input.
 */
export function isTouchDevice(): boolean {
  if (typeof window === "undefined") return false;
  // Primary check: coarse pointer (finger touch)
  if (window.matchMedia("(pointer: coarse)").matches) return true;
  // Secondary check: any pointer is coarse (multi-input device)
  if (window.matchMedia("(any-pointer: coarse)").matches) return true;
  // Tertiary check: touch event support + touch points
  if ("ontouchstart" in window || navigator.maxTouchPoints > 0) return true;
  return false;
}

/** Escape text placed into the program row's HTML. */
function escapeHtml(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}
